  "summary": "The code contained critical security vulnerabilities including command injection and unbounded file uploads, alongside performance bottlenecks due to blocking I/O. The refactored code introduces temporary directory isolation, stream error handling, and functional programming patterns to improve robustness and maintainability.",
  "fixed_code": "const express = require('express');\nconst crypto = require('crypto');\nconst fs = require('fs');\nconst os = require('os');\nconst path = require('path');\nconst { execFile } = require('child_process');\nconst { pipeline } = require('stream');\n\nconst app = express();\napp.use(express.json({ limit: '1mb' }));\nconst UPLOADS = path.join(__dirname, 'uploads');\nif (!fs.existsSync(UPLOADS)) fs.mkdirSync(UPLOADS);\n\napp.post('/imports', (req, res) => {\n    const repo = String(req.body.repo || '');\n    if (!/^https:\\/\\/github\\.com\\/[\\w.-]+\\/[\\w.-]+(\\.git)?$/.test(repo)) {\n        return res.status(400).json({ error: 'unsupported repository url' });\n    }\n    const tmpDir = fs.mkdtempSync(path.join(os.tmpdir(), 'git-'));\n    execFile('git', ['clone', '--depth', '1', '--', repo, tmpDir], { timeout: 60000 }, (err) => {\n        if (err) fs.rmSync(tmpDir, { recursive: true, force: true });\n        res.status(err ? 500 : 202).json({ status: err ? 'failed' : 'queued' });\n    });\n});\n\napp.put('/upload', (req, res) => {\n    const dest = path.join(UPLOADS, `${crypto.randomUUID()}.bin`);\n    pipeline(req, fs.createWriteStream(dest), (err) => {\n        if (err) return res.sendStatus(500);\n        res.sendStatus(201);\n    });\n});\n\n/** @param {Array<{id: string|number}>} users */\nfunction collectIds(users) {\n    return users.map(u => u.id);\n}\n\napp.listen(process.env.PORT || 3000);\nmodule.exports = { collectIds };"
}
